// CI/CD System

// Define Deployment Pipelines
pipeline Build {
  mandatory Operations {
    // All pipelines must run 'Build' and 'Unit Test' stages.
    mandatory Build
    mandatory UnitTest
  }

  // Staging deployment is mandatory and only runs after Unit Test passes.
  mandatory Staging {
    mandatory Operations {
      // Staging deployment is mandatory
      mandatory Staging
    }
    optional Staging
    mandatory UnitTest
    mandatory UnitTest
    mandatory UnitTest
    optional UnitTest
    optional UnitTest
  }

  // Production deployment requires Staging to succeed AND Integration Test & Security Scan to pass.
  mandatory Production {
    mandatory Operations {
      mandatory IntegrationTest
      mandatory SecurityScan
    }
    optional Production
    optional Production
    optional Production
    optional Production
    optional Production
    optional Production
  }

  // 'Canary' strategy
  optional Canary {
    mandatory Operations {
      mandatory Monitoring
    }
    optional Production
    optional Production
    optional Production
    optional Production
    optional Production
    optional Production
  }

  // Blue/Green strategy
  optional BlueGreen {
    mandatory Operations {
      mandatory Monitoring
    }
    optional Production
    optional Production
    optional Production
    optional Production
    optional Production
    optional Production
  }

  // Hotfix pipeline bypasses Staging & Integration Test, but requires Manual QA Approval & must pass Security Scan.
  mandatory Hotfix {
    mandatory Operations {
      mandatory SecurityScan
      mandatory UnitTest
    }
    optional UnitTest
    optional UnitTest
    optional UnitTest
    optional UnitTest
    optional UnitTest
  }
```

